\begin{enumerate}
        \item Any proper forcing is $\vec S$-preserving.
        \item When $K=\{ \omega_1\}$ and $\vec{S}=S \subset \omega_1$, the definition of $\vec S$-preserving is identical to the usual definition of $S$-proper forcing.
        \item Let $\vec{S}$ be such that each $S_{\eta} \in \vec S$ is stationary, co-stationary in $\eta \cap Cof(\omega)$.
       Then an example of a non-proper, $\vec S$ preserving forcing is the forcing poset $Club(S_\eta)$, i.e, the forcing which adds an unbounded subset to $S_\eta$ which is closed under $\omega$-sequences, via countable approximations.
    \end{enumerate}

Let $\kappa$ be an inaccessible cardinal. Let $\vec S= \langle S_{i} \mid i< \kappa \rangle$ be mutually stationary. We say a forcing poset $\mathbb{P}$ is a $ \vec S$-coding if $\delta \le \kappa$ and $\mathbb{P}= \langle \mathbb{P}_\alpha, \dot{\mathbb{Q}}_\alpha \mid \alpha<\delta \rangle $ satisfies the following:
    \begin{itemize}
        \item $\mathbb{P}$ is a countable support iteration
        \item For any $\alpha<\delta$, one of the followings holds:
        \begin{enumerate}

            \item Assume that $\alpha$ is inaccessible and $\mathbb{P}_\alpha$ is forcing equivalent to a forcing of size less or equal than $\alpha$.\footnote{We say two forcing $P$ and $Q$ are equivalent if their Boolean completions $B(P)$ and $B(Q)$ are isomorphism.} Assume that in $V^{\mathbb{P}_\alpha}$, $\langle B_\beta\mid \beta <2^\alpha\rangle$ is an enumeration of $V_{\alpha}$. Then $\dot{Q}_\alpha$ is allowed to be $$\prod_{j\in B_\beta}Club(S_{\alpha\cdot(\beta+1)+2j}) \times \prod_{j\notin B_\beta}Club(S_{\alpha\cdot(\beta+1)+2j+1})$$ using countable support.

             \item In all other cases, we have that $\Vdash_{\mathbb{P}_\alpha}\dot{Q}_\alpha$ is proper.
        \end{enumerate}
    \end{itemize}
    Let $\eta$ be an regular cardinal, we  say $\mathbb{P}$ is an $\eta$-$\vec S$ coding if (1) is replaced by
    \begin{itemize}
        \item[(1')]  $\alpha \ge \eta$ is inaccessible and $\mathbb{P}_\alpha$ is forcing equivalent to a forcing of size less or equal than $\alpha$. In $V^{\mathbb{P}_\alpha}$, $\langle B_\beta\mid \beta <2^\alpha\rangle$ is an enumeration of $V_\alpha$. Then $\dot{Q}_\alpha$ is allowed  to be $$\prod_{j\in B_\beta}Club(S_{\alpha\cdot(\beta+1)+2j}) \times \prod_{j\notin B_\beta}Club(S_{\alpha\cdot(\beta+1)+2j+1})$$
    \end{itemize}

\label{lem: stationary preservation}
    Suppose that $\vec S$ is stationary, co-stationary. Suppose $\mathbb{P}$ is an $\vec S$ coding forcing. Then for any $i \in \kappa$, the followings are equivalent:
    \begin{itemize}
        \item[(a)] $\Vdash_{\mathbb{P}} S_{i}$ contains an $\omega$-club.
        \item[(b)] there are $\beta,\alpha,j$ and a set $B_{\beta} \subset V_{\alpha}$ such that $j \in B_{\beta}$ if $\beta\cdot(\alpha+1)+2j=i$ and $i$ is even and $j \notin B_{\beta}$ if $\beta\cdot(\alpha+1)+2j+1=i$ and  $i$ is odd.
    \end{itemize}

Suppose $\alpha$ is in inaccessible in $L$ and $X\subseteq P(\alpha)$. We say $\vec S$ codes $X \subset \alpha$ if
    \begin{enumerate}
        \item For any even $i\in [\alpha, (\alpha^+)^L)$, one of $S_{i}$ and $S_{i+1}$ contains a club.
        \item For any $x\in X$,      there is a $\beta< \alpha$ such that $$j\in x\text{ if and only if }S_{\alpha\cdot(\beta+1)+2i}\text{ contains a club}$$ and $$j\notin x\text{ if and only if }S_{\alpha\cdot(\beta+1)+2i+1}\text{ contains a club}$$
    \end{enumerate}
    Let $\vec C=\langle C_i \mid i\in [\alpha, (\alpha^+)^L) \rangle$ be a club sequence which witnesses (2), then we say that $\vec C$ is a $\vec S$ code for $X$.

Suppose that $V=L$ and $\delta$ is a reflecting cardinal. Then there is a forcing poset $P$ such that in $L^{P}$, the following statements hold:
    \begin{enumerate}
        \item BPFA
        \item $\omega_1=\omega_1^L$ and $\omega_2=\delta$.
        \item The nonstationary ideal on $\omega_1$ is $\Sigma_1(\{\omega_1\})$-definable over $\langle H(\omega_2), \in \rangle$.
    \end{enumerate}

We first choose a sequence $\langle S_ \alpha\mid \alpha\in \mathop{\textrm{Lim}}(\delta)\rangle$ uniformly in $\alpha< \delta$ satisfying
    \begin{itemize}
        \item $S_\alpha\subset \alpha$
        \item If $\alpha$ is a regular cardinal, then $S_\alpha$ is stationary co-stationary in $\alpha\cap \textrm{Cof}(\omega)$.
    \end{itemize}
     The existence of such a sequence $\langle S_ \alpha\mid \alpha\in \mathop{\textrm{Lim}}(\delta)\rangle$  follows from the fact that $\diamondsuit_{\lambda}$ holds in $L$ for any $L$-cardinal $\lambda$ and is a routine construction. 

     Now we define the forcing poset $P$. The forcing $P=\langle P_\alpha, \dot{Q}_\alpha \mid \alpha<\delta \rangle $ will be a countable support iteration of length $\delta$. We require the size of each iterand to be smaller than $\delta$. As a consequence $P$ satisfies $\delta$-cc.
We demand that  $\dot{Q}_\alpha$ is trivial unless $\alpha$ is an inaccessible cardinal and $P_\alpha\subset L_\alpha$. We split into two cases if $\alpha$ is inaccessible.
     \begin{itemize}
        \item ($\alpha$ is Mahlo) We follow an idea from Goldstern-Shelah \cite{GS}.
        Choose a $A\subset \omega_1$ and a $\Sigma_1$ formula $\psi(x,y)$. $A$ and $\psi$ is chosen in a bookkeeping way so that during the whole iteration, each pair $(A,\psi)$ will be dealt with unboundedly many times. Since $\delta$ is reflecting, whenever there is a $\alpha$-$\vec S_{>\alpha}$ coding forcing poset $Q$ which adds a witness to $\psi(x,A)$, there is such a $Q$ of size less than $\delta$. In this case, let $\dot{Q}_\alpha$ be the name of $Q$ and use this forcing at stage $\alpha$. When there is no such $Q$, we set $\dot{Q}_\alpha$ to be trivial forcing.
        \item ($\alpha$ is inaccessible but not Mahlo) $\dot{Q}_\alpha$ is trivial unless $\vert P_\alpha\vert\le \alpha$. Work in $L[G_\alpha]$, where $G_\alpha$ is a $L$-$P_\alpha$ generic filter. $\vert P_\alpha\vert= \alpha$ is inaccessible. We choose $\langle B_\beta\mid \beta <2^\alpha\rangle$ to be an enumeration of $P(\alpha)^{V[G_\alpha]}$. Let $Q$ be the forcing $$\prod_{i\in B_\beta}Club(S_{\alpha\cdot(\beta+1)+2i}) \times \prod_{i\notin B_\beta}Club(S_{\alpha\cdot(\beta+1)+2i+1})$$ with countable support. Then we force with $Q$ at stage $\alpha$.
     \end{itemize}
     It follows from the definition of $P$ that for any $\alpha <\delta$, the forcing $\dot{Q}_{\alpha}$ is forced to be a $\alpha-\vec S$ coding forcing. Applying Lemma \ref{lem: composition}, we know that $P$ is a $\vec{S}$-coding forcing. Moreover, for any $\alpha$ Mahlo, the tail $P /P_\alpha$ is a $\alpha$-$\vec S_{>\alpha}$ coding.


     Now as $P$ is $\vec S$-preserving, $P$ preserves $\omega_1$. On the other hand, $P$ is $\delta$-c.c and $P$ preserves cardinals above $\delta$. By the definition of the forcing in the inaccessible but not Mahlo case, all cardinals below $\delta$ are collapsed to $\omega_1$. In summary, $\omega_1^{L^P}=\omega_1^L$ and $\omega_2^{L^P}=\delta$.

     \begin{lemma}
        $P \Vdash $ $\mathsf{BPFA}$.
     \end{lemma}

     \begin{proof}
        Work in $L[G]$. Let $A\subset \omega_1$ and $Q \in L[G]$ be a proper forcing which adds a witness to the $\Sigma_1$-formula $\psi(x,A)$. Now let $\alpha$ be a stage such that $A\in L[G_\alpha]$, $\alpha$ is Mahlo and $( A,\psi)$ is to be dealt with at stage $\alpha$. In $L[G]$, the forcing $P/P_\alpha*Q$ is a $\alpha-\vec S_{>\alpha}$ coding forcing adding a witness to $\psi(x,A)$. Hence, we must be in the first case of the definition of our iteration at stage $\alpha$ and $Q_\alpha$ is a $\alpha-\vec S_{>\alpha}$ coding forcing which adds a witness to $\psi(x,A)$. Thus $H(\omega_2)^{L[G_{\alpha+1}]}\models \exists x\psi(x, A)$. By upward absoluteness, $H(\omega_2)^{L[G]}\models \exists x\psi(x, A)$.
     \end{proof}
     \begin{lemma}\label{lem: stat des}
      Work in $L[G]$.  Let $S$ be a subset of $\omega_1$, then the following are equivalent:
        \begin{itemize}
            \item[(a)] $S$ is stationary.
            \item[(b)] there is a $\alpha$ inaccessible in $L$ with $P_\alpha\subseteq L_\alpha$ and $S$ is stationary in $L[G_\alpha]$.
            \item[(c)] there is a $\alpha$ inaccessible in $L$, there is $\vec{C} \in L[G_{\alpha+1}]$ which is a $\vec S$ code for  $P(\alpha)^{L[G_\alpha]}$, and there is a transitive model $M$ of $\mathsf{ZF}^-$ such that
            $\vec{C} \in M$ and $M$ thinks that $S$ is stationary.
        \end{itemize}

     \end{lemma}
     \begin{proof}
         ((a) $\rightarrow$ (c)) Let $\alpha$ be inaccessible but not Mahlo and consider stage $\alpha$ of the iteration which we can assume to be  such that $S\in L[G_\alpha]$ and $\vert P_\alpha\vert\le \alpha$. Now $Q_\alpha$ forces the existence of a $\vec{C}$-sequence which is an $\vec S$ code for $P(\alpha)^{L[G_\alpha]}$.   Any transitive $M$ which contains $\vec{C}$ is as desired in (c), moreover $M$ will automatically think that $S$ is stationary if $S$ is stationary in $L[G]$.

         ((b) $\rightarrow$ (a)) The tail of forcing $P/P_\alpha$ is $\alpha$-$S_{>\alpha}$ coding. Now the proof of Lemma \ref{lem: stationary preservation} shows $P/P_\alpha$ preserves stationarity of $S$.

         ((c) $\rightarrow$ (b)) If $M$ is as in the assumption, $P(\alpha)^{L[G_{\alpha}]}$ is a subset of $M$, and if $M$ thinks that $S$ is stationary, so must $V_{\alpha+1}^{L[G_{\alpha}]}=P(\alpha)^{L[G_{\alpha}]}$, and hence $L[G_{\alpha}]$.
     \end{proof}

     We now present the $\Sigma_1$ definition of stationary subsets of $\omega_1$ over $(H(\omega_2), \in, \{\omega_1\})$. Let $\psi(x)$ describe the following statement: there are objects $A$ and $M$ such that
     \begin{itemize}
         \item[(i)] $A= \langle C_i \mid i
         \in [\alpha, \beta) \rangle$ is a sequence with $C_i$ is an $\omega$-club in $\sup (C_i \cap Ord)=\eta_i$.
         \item[(ii)] All $\eta_i$ are regular cardinals in $L$. $\eta_\alpha=\alpha$ is inaccessible in $L$.
         \item[(iii)] $M$ is a transitive ZFC$^-$ model with $\omega_1=\omega_1^M$, $((\alpha^+)^L)^M= (\alpha^+)^L$, and $x\in M$.
         \item[(iv)] $M\models x \subset \omega_1$ is stationary.
         \item[(v)] $M\models A$ is a $\vec S$ codes for $P(\alpha)$.
     \end{itemize}
     It is routine to check (i), (iii), (iv) and (v) are all $\Sigma_1$ over $\langle H(\omega_2),\in,  \{\omega_1\} \rangle$. For (ii), as $L[G]\models BPFA$, we can apply a trick of Todorcevic (cf. Proof of Lemma 4, \cite{To02}) to get $\Sigma_1$ formulas $\psi_0 (x)$ and $\psi_1 (x)$ such that $H(\omega_2)\models \psi_0(\beta)$ if and only if $\beta$ is a regular cardinal in $L$ and $H(\omega_2)\models \psi_1(\beta)$ if and only if $\beta$ is an inaccessible cardinal in $L$. 

 Here $\psi_0(x)$ is the formula describing the existence of a specialization function of the tree $T_x$, where $T_x$ is derived from the canonical global square sequence in $L$. It is a consequence of $\mathsf{BPFA}$ that $x$ is uncountable regular in $L$ if and only if such a specialization function exists. Now $\psi_1(x)$ is a formula says $\alpha$ is regular and a limit of regular cardinals in $L$.

    It is now clear that $\psi(x)$ is $\Sigma_1$ over $\langle H(\omega_2),\in, \{\omega_1\} \rangle.$ What is left is to show that $\psi(x)$ indeed characterizes stationarity.

     \begin{lemma}
         In $L[G]$, for any $x\subseteq \omega_1$, $H(\omega_2)\models\psi(x)$ if and only if $x$ is stationary.
     \end{lemma}
     \begin{proof}
       If $x\subset \omega_1$ is stationary, then, by Lemma \ref{lem: stat des} (c), we do immediately get a witness $M \in H(\omega_2)$ and an $A$ so that $\psi(x)$ holds.

        Conversely, let $x$, $A$, $M$ be as given by the definition of $\psi(x)$, we check that $x$ is stationary. But if  $\psi(x)$ holds, then $M$ thinks that $A$ is a $\vec{S}$-code for $P(\alpha)$. By item  $(ii)$ of $\psi$, this also means that $A$ is a $\vec{S}$-code for $P(\alpha)$ and by (c) of Lemma \ref{lem: stat des} it is true that $x$ is indeed stationary. 
     \end{proof}

\label{lem: stat des}
      Work in $L[G]$.  Let $S$ be a subset of $\omega_1$, then the following are equivalent:
        \begin{itemize}
            \item[(a)] $S$ is stationary.
            \item[(b)] there is a $\alpha$ inaccessible in $L$ with $P_\alpha\subseteq L_\alpha$ and $S$ is stationary in $L[G_\alpha]$.
            \item[(c)] there is a $\alpha$ inaccessible in $L$, there is $\vec{C} \in L[G_{\alpha+1}]$ which is a $\vec S$ code for  $P(\alpha)^{L[G_\alpha]}$, and there is a transitive model $M$ of $\mathsf{ZF}^-$ such that
            $\vec{C} \in M$ and $M$ thinks that $S$ is stationary.
        \end{itemize}

There are $\Sigma_1(\vec{C}, \vec{T}^0)$-formulas $\Phi(r)$ and $\Psi(S)$ where the formula $\Phi(r)$ defines a set of reals such that every member is an almost disjoint code for an $\aleph_1$-sized, transitive models which can be used to compute the sequence $\vec{T}^{>0}$ of Suslin trees correctly (these models are the suitable models mentioned earlier). The formula $\Psi(S)$ then defines stationary subsets of $W_{\omega_2}$ in the following way:
\begin{itemize}
\item[$\Psi(S)$] if and only if there is an $\aleph_1$-sized, transitive model $N$ which contains $\vec{C}$ and $\vec{T}^0$ such that $N$ models that
\begin{itemize}
\item There exists a real $x$ such that $\Phi(x)$ holds, i.e. $x$ is a code for a suitable model $M$.
\item There exists an ordinal $\alpha$ in the suitable model $M$ such that $\vec{T}'$ is the $\alpha$-th $\omega_1$ block of the definable sequence of independent Suslin trees as computed in $M$ and $N$ sees a full pattern on $\vec{T}'$.
\item $\forall \beta < \omega_1$ $( \beta \in S$ if and only if $\vec{T}' (\beta)$ has a branch).
\item $\forall \beta < \omega_1$ $(\beta \notin S$ if and only if $\vec{T}' (\beta)$ is special).
\end{itemize}
\end{itemize}
Note that $\Psi(S)$ is of the form $\exists N (N \models...)$, thus $\Psi$ is a $\Sigma_1$-formula.

There is a $\Sigma_1(\vec{C}, \vec{T}^0)$-formula $\Psi(h)$ which defines the generically added Suslin trees $(h_{\alpha} \, : \, \alpha < \omega_2)$ of $W_2$:
\begin{itemize}
\item[$\Psi(h)$] if and only if there is an $\aleph_1$-sized, transitive model $N$ which contains $\vec{C}$ and $\vec{T}^0$ such that $N$ models that
\begin{itemize}
\item There exists a real $x$ such that $\Phi(x)$ holds, i.e. $x$ is a code for a suitable model $M$.
\item There exists an ordinal $\alpha$ in the suitable model $M$ such that $\vec{T}'$ is the $\alpha$-th $\omega_1$ block of the definable sequence of independent Suslin trees as computed in $M$ and $N$ sees a full pattern on $\vec{T}'$.
\item $\forall \beta < \omega_1$ $( \beta \in h$ if and only if $\vec{T}' (\beta)$ has a branch).
\item $\forall \beta < \omega_1$ $(\beta \notin h$ if and only if $\vec{T}' (\beta)$ is special).
\end{itemize}
\end{itemize}
Note that $\Psi(h)$ is of the form $\exists N (N \models...)$, thus $\Psi$ is a $\Sigma_1$-formula.

